CREATE TABLE `duty_rate` (
  `id` int NOT NULL AUTO_INCREMENT,
  `country` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `hs_code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `direction` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'import',
  `duty_type` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `trade_partner` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `duty_rate` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rate_value` float DEFAULT NULL,
  `rate_kind` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tariff_basis` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `note` text COLLATE utf8mb4_unicode_ci,
  `source` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `effective_from` datetime DEFAULT NULL,
  `effective_to` datetime DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `fetched_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_duty_country_code_dir_type_partner_rate` (`country`,`hs_code`,`direction`,`duty_type`,`trade_partner`,`duty_rate`),
  KEY `ix_duty_rate_duty_type` (`duty_type`),
  KEY `ix_duty_rate_hs_code` (`hs_code`),
  KEY `ix_duty_fetch` (`country`,`hs_code`,`direction`)
) ENGINE=InnoDB AUTO_INCREMENT=162 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
